{
  "gaps": [
    {
      "concept": "Glucosuria causes osmotic diuresis, producing polyuria and polydipsia; insulin deficiency also causes catabolic weight loss and polyphagia.",
      "why_tested": "A patient presents with thirst, frequent urination, increased appetite, and unexplained weight loss.",
      "yield": "hi"
    },
    {
      "concept": "C-peptide reflects endogenous insulin secretion: it is low in established type 1 diabetes and often preserved in type 2 diabetes.",
      "why_tested": "A stem asks whether an insulin-treated patient still produces insulin.",
      "yield": "hi"
    },
    {
      "concept": "Type 1 diabetes clusters with autoimmune thyroid disease, celiac disease, and Addison disease.",
      "why_tested": "A patient with diabetes develops another autoimmune disorder.",
      "yield": "hi"
    },
    {
      "concept": "Latent autoimmune diabetes in adults has islet autoantibodies and gradual beta-cell loss despite an initial type 2 appearance.",
      "why_tested": "An adult labeled with type 2 diabetes progressively requires insulin and has positive GAD antibodies.",
      "yield": "mid"
    },
    {
      "concept": "Gestational diabetes results from pregnancy-induced insulin resistance, particularly placental lactogen, and increases later type 2 diabetes risk.",
      "why_tested": "Hyperglycemia first appears during pregnancy and resolves after delivery.",
      "yield": "mid"
    },
    {
      "concept": "Chronic pancreatitis, cystic fibrosis, and hemochromatosis can cause diabetes through pancreatic damage.",
      "why_tested": "A patient develops diabetes alongside pancreatic disease or iron overload.",
      "yield": "mid"
    },
    {
      "concept": "Glucocorticoid exposure, Cushing syndrome, and acromegaly can cause secondary diabetes through insulin resistance.",
      "why_tested": "New hyperglycemia follows steroid treatment or accompanies excess cortisol or growth hormone.",
      "yield": "mid"
    },
    {
      "concept": "Without unequivocal symptomatic hyperglycemia, diabetes diagnosis requires two abnormal test results.",
      "why_tested": "An asymptomatic patient has one glucose or HbA1c value above the diagnostic threshold.",
      "yield": "hi"
    },
    {
      "concept": "Iron deficiency can falsely elevate HbA1c; altered red-cell turnover calls for plasma glucose testing.",
      "why_tested": "HbA1c conflicts with measured glucose in a patient with anemia.",
      "yield": "mid"
    },
    {
      "concept": "Fructosamine reflects glycemia over approximately two to three weeks and can assess control when HbA1c is unreliable.",
      "why_tested": "A patient with hemolysis needs a marker of recent glycemic control.",
      "yield": "mid"
    },
    {
      "concept": "Early diabetic nephropathy causes glomerular hyperfiltration from increased intraglomerular pressure before GFR declines.",
      "why_tested": "A newly diagnosed patient has elevated GFR despite emerging kidney injury.",
      "yield": "hi"
    },
    {
      "concept": "Diabetic nephropathy hyalinizes both afferent and efferent renal arterioles; efferent involvement distinguishes it from typical hypertensive nephrosclerosis.",
      "why_tested": "Renal histology asks which arteriole distinguishes diabetes from hypertension.",
      "yield": "hi"
    },
    {
      "concept": "Diabetic nephropathy also causes diffuse mesangial expansion and glomerular basement-membrane thickening.",
      "why_tested": "A renal biopsy shows diabetic injury without nodular glomerulosclerosis.",
      "yield": "mid"
    },
    {
      "concept": "Nonproliferative diabetic retinopathy features dot-blot hemorrhages, hard exudates, and cotton-wool spots without neovascularization.",
      "why_tested": "Fundus findings must be classified as nonproliferative or proliferative retinopathy.",
      "yield": "hi"
    },
    {
      "concept": "Proliferative retinopathy can cause vitreous hemorrhage and tractional retinal detachment.",
      "why_tested": "A patient with retinal neovascularization develops sudden vision loss.",
      "yield": "mid"
    },
    {
      "concept": "Diabetic macular edema results from retinal vascular leakage and causes central vision loss.",
      "why_tested": "A diabetic patient has reduced central vision with retinal thickening.",
      "yield": "mid"
    },
    {
      "concept": "Diabetic ischemic third-nerve palsy usually spares the pupil, unlike a compressive posterior communicating artery aneurysm.",
      "why_tested": "A diabetic patient develops ptosis and diplopia with preserved pupillary constriction.",
      "yield": "hi"
    },
    {
      "concept": "Diabetic neuropathy can cause Charcot arthropathy: a warm, swollen, relatively painless foot with bony destruction.",
      "why_tested": "Foot imaging shows joint collapse despite little pain.",
      "yield": "mid"
    },
    {
      "concept": "Diabetes accelerates atherosclerosis, increasing ischemic stroke and peripheral arterial disease as well as coronary disease.",
      "why_tested": "A patient with longstanding diabetes develops claudication or ischemic stroke.",
      "yield": "hi"
    },
    {
      "concept": "Hyperglycemia impairs neutrophil chemotaxis and phagocytosis, contributing to infection susceptibility.",
      "why_tested": "A stem asks why infections are unusually frequent or severe in diabetes.",
      "yield": "mid"
    },
    {
      "concept": "Type 1 diabetes requires exogenous insulin; insulin's major adverse effects are hypoglycemia and weight gain.",
      "why_tested": "A newly diagnosed type 1 patient needs treatment, or an insulin-treated patient develops sweating and confusion.",
      "yield": "hi"
    },
    {
      "concept": "Rapid-acting insulin analogs cover meals; long-acting analogs provide basal insulin.",
      "why_tested": "A question asks which insulin replaces meal-related versus fasting secretion.",
      "yield": "mid"
    },
    {
      "concept": "Metformin reduces hepatic gluconeogenesis; adverse effects include gastrointestinal upset, vitamin B12 deficiency, and rare lactic acidosis.",
      "why_tested": "A type 2 patient starts first-line medication and develops diarrhea or otherwise unexplained neuropathy.",
      "yield": "hi"
    },
    {
      "concept": "Sulfonylureas close beta-cell ATP-sensitive potassium channels, increasing insulin release; they can cause hypoglycemia and weight gain.",
      "why_tested": "A type 2 patient develops hypoglycemia after starting a drug that requires functioning beta cells.",
      "yield": "hi"
    },
    {
      "concept": "GLP-1 receptor agonists increase glucose-dependent insulin secretion, suppress glucagon, slow gastric emptying, and promote weight loss; nausea is common.",
      "why_tested": "A patient loses weight but develops nausea after starting injectable diabetes therapy.",
      "yield": "hi"
    },
    {
      "concept": "DPP-4 inhibitors prolong endogenous incretin activity and are generally weight-neutral with low hypoglycemia risk.",
      "why_tested": "A question contrasts an incretin-preserving drug with a GLP-1 receptor agonist.",
      "yield": "mid"
    },
    {
      "concept": "SGLT2 inhibitors block proximal-tubule glucose reabsorption, causing glucosuria; adverse effects include genital mycoses and euglycemic ketoacidosis.",
      "why_tested": "A treated patient has glucosuria, a genital yeast infection, or ketoacidosis with modest glucose elevation.",
      "yield": "hi"
    },
    {
      "concept": "Thiazolidinediones activate PPAR-gamma to improve insulin sensitivity; adverse effects include edema, heart-failure worsening, weight gain, and fractures.",
      "why_tested": "A patient develops edema after starting pioglitazone.",
      "yield": "hi"
    },
    {
      "concept": "Alpha-glucosidase inhibitors delay intestinal carbohydrate absorption and commonly cause flatulence and diarrhea.",
      "why_tested": "A diabetes drug blunts postprandial glucose excursions but causes gastrointestinal symptoms.",
      "yield": "mid"
    },
    {
      "concept": "Pramlintide is an amylin analog that suppresses glucagon and delays gastric emptying; combined with insulin, it can cause hypoglycemia.",
      "why_tested": "An insulin-treated patient receives an amylin analog for postprandial glucose control.",
      "yield": "lo"
    }
  ]
}
